// Open-Meteo hourly reply -> global frost_forecast {ts, night_min_c, frost, until, min_c}.
// 'Tonight' = every hourly value from the current hour until 09:00 local (tomorrow's, once it is past 09:00).
const MIN_C = __FROST_MIN_C__;
var p = msg.payload;
if (!p || typeof p !== 'object' || !p.hourly || !Array.isArray(p.hourly.time) || !Array.isArray(p.hourly.temperature_2m)) {
  node.status({ fill: 'red', shape: 'ring', text: 'fetch failed ' + new Date().toLocaleTimeString() + ' (' + (msg.statusCode || 'no reply') + ')' });
  node.warn('frost forecast: bad reply ' + (msg.statusCode || '') + ' ' + String(typeof p === 'string' ? p : '').slice(0, 120));
  return null;
}
var off = (typeof p.utc_offset_seconds === 'number') ? p.utc_offset_seconds : 36000;
var local = new Date(Date.now() + off * 1000).toISOString();          // the site's wall clock, as 'YYYY-MM-DDTHH:...'
var fromH = local.slice(0, 13) + ':00';
var day = local.slice(0, 10);
if (+local.slice(11, 13) >= 9) day = new Date(Date.parse(day + 'T00:00:00Z') + 86400000).toISOString().slice(0, 10);
var until = day + 'T09:00';
var temps = [];
for (var i = 0; i < p.hourly.time.length; i++) {
  var tm = p.hourly.time[i], v = p.hourly.temperature_2m[i];
  if (tm >= fromH && tm <= until && typeof v === 'number') temps.push(v);
}
if (!temps.length) { node.status({ fill: 'red', shape: 'ring', text: 'no hours before ' + until }); return null; }
var lo = Math.min.apply(null, temps);
var fc = { ts: Date.now(), night_min_c: lo, frost: lo <= MIN_C, until: until, min_c: MIN_C, hours: temps.length };
global.set('frost_forecast', fc);
node.status({ fill: fc.frost ? 'blue' : 'green', shape: 'dot', text: 'min ' + lo + ' C to ' + until.slice(5) + (fc.frost ? ' FROST' : '') + ' @' + new Date().toLocaleTimeString() });
return { topic: 'bsf/hotwater/frost_forecast', payload: fc };
